1	export type Customer = { yearsWithMHPCO: number };
2	
3	export type Scenario = {
4	  customer: Customer;
5	  steps: Step[];
6	};
7	
8	export type Step =
9	  | { op: "quote"; items: Item[] }
10	  | { op: "claim"; policy: number; incident: Incident };
11	
12	export type Item = {
13	  type: string;
14	  material?: string;
15	  enchantment?: number;
16	  cursed?: boolean;
17	};
18	
19	export type Incident = {
20	  cause: string;
21	  damages: Damage[];
22	};
23	
24	export type Damage = {
25	  itemType: string;
26	  amount: number;
27	};
28	
29	export type Result = { premium: number } | { payout: number; remainingCap: number };
30	
31	const PROCESSING_FEE = 5;
32	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
33	
34	// The catalogue of insurable item types. Each type carries both figures the
35	// office needs: what it costs to insure (base premium) and what it is worth
36	// when destroyed (insurance value). Keeping them in one row means a new item
37	// type is one edit, and the two figures can never drift apart.
38	const CATALOGUE: Record<string, { basePremium: number; insuranceValue: number }> = {
39	  sword: { basePremium: 100, insuranceValue: 1000 },
40	  amulet: { basePremium: 60, insuranceValue: 600 },
41	  staff: { basePremium: 80, insuranceValue: 800 },
42	  potion: { basePremium: 40, insuranceValue: 400 },
43	  rune: { basePremium: 25, insuranceValue: 250 },
44	  moonstone: { basePremium: 25, insuranceValue: 250 },
45	};
46	
47	// Both catalogue figures are read through this one row lookup, so an item's type
48	// is resolved against the catalogue in exactly one place.
49	const catalogueEntryFor = (item: Item) => CATALOGUE[item.type];
50	
51	const basePremiumOf = (item: Item): number => catalogueEntryFor(item).basePremium;
52	
53	const BLOCK_SIZE = 3;
54	const BLOCK_BASE_PREMIUM = 60;
55	
56	const formsABuildingBlock = (alikeItems: Item[]): boolean =>
57	  alikeItems.length === BLOCK_SIZE;
58	
59	const sumOfBasePremiums = (items: Item[]): number =>
60	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
61	
62	const CURSE_SURCHARGE_RATE = 0.5;
63	const HIGH_ENCHANTMENT_LEVEL = 5;
64	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
65	
66	const isCursed = (item: Item): boolean => item.cursed === true;
67	
68	// An unenchanted item is enchantment 0, so every threshold reads the level the
69	// same way. The MHPCO sets several enchantment thresholds for different rules;
70	// each names its own level and compares through here.
71	const enchantmentLevelOf = (item: Item): number => item.enchantment ?? 0;
72	
73	const carriesEnchantmentSurcharge = (item: Item): boolean =>
74	  enchantmentLevelOf(item) >= HIGH_ENCHANTMENT_LEVEL;
75	
76	// A rate table prices one subject: every row whose risk applies contributes its
77	// rate, and the total is their sum. Both the item surcharges and the policy-wide
78	// modifiers are rate tables — they differ only in what they are applied to.
79	type RateTable<Subject> = { appliesTo: (subject: Subject) => boolean; rate: number }[];
80	
81	const totalRateFrom = <Subject,>(table: RateTable<Subject>, subject: Subject): number =>
82	  table.reduce((total, row) => (row.appliesTo(subject) ? total + row.rate : total), 0);
83	
84	// Every item-specific surcharge is a rate on THAT item's base premium, charged
85	// when its risk applies. Adding a new one means adding a row here — nothing else.
86	const ITEM_SURCHARGES: RateTable<Item> = [
87	  { appliesTo: isCursed, rate: CURSE_SURCHARGE_RATE },
88	  { appliesTo: carriesEnchantmentSurcharge, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
89	];
90	
91	const surchargeRateOn = (item: Item): number => totalRateFrom(ITEM_SURCHARGES, item);
92	
93	const itemSurchargesOn = (items: Item[]): number =>
94	  items.reduce((sum, item) => sum + basePremiumOf(item) * surchargeRateOn(item), 0);
95	
96	// Items of the same type are "alike"; each group is priced together so a
97	// building block can be recognised.
98	const alikeItemGroupsIn = (items: Item[]): Item[][] => [
99	  ...items
100	    .reduce(
101	      (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
102	      new Map<string, Item[]>(),
103	    )
104	    .values(),
105	];
106	
107	const basePremiumOfAlikeItems = (alikeItems: Item[]): number =>
108	  formsABuildingBlock(alikeItems) ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(alikeItems);
109	
110	const policyBaseOf = (items: Item[]): number =>
111	  alikeItemGroupsIn(items).reduce(
112	    (sum, alikeItems) => sum + basePremiumOfAlikeItems(alikeItems),
113	    0,
114	  );
115	
116	// Rounding always favours the MHPCO: premiums up, payouts down.
117	const premiumRoundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
118	
119	const LOYALTY_YEARS = 2;
120	const LOYALTY_DISCOUNT_RATE = -0.2;
121	
122	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = -0.15;
123	
124	// Each item in a quote is treated as a first insurance regardless of customer
125	// history, so this surcharge is unconditional.
126	const appliesUnconditionally = (): boolean => true;
127	
128	const isLongStanding = ({ customer }: QuoteContext): boolean =>
129	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
130	
131	const isFollowUpContract = ({ precedingQuotes }: QuoteContext): boolean =>
132	  precedingQuotes > 0;
133	
134	// A quote is priced from the customer plus its place in the scenario's history.
135	type QuoteContext = { customer: Customer; precedingQuotes: number };
136	
137	// Every policy-wide modifier is a rate on the UNMODIFIED policy base — never on a
138	// base that already includes the item surcharges. Surcharges carry a positive
139	// rate, discounts a negative one. Adding a new one means adding a row here.
140	const POLICY_MODIFIERS: RateTable<QuoteContext> = [
141	  { appliesTo: appliesUnconditionally, rate: FIRST_INSURANCE_SURCHARGE_RATE },
142	  { appliesTo: isLongStanding, rate: LOYALTY_DISCOUNT_RATE },
143	  { appliesTo: isFollowUpContract, rate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE },
144	];
145	
146	const policyModifiersOn = (policyBase: number, context: QuoteContext): number =>
147	  policyBase * totalRateFrom(POLICY_MODIFIERS, context);
148	
149	const quoteFor = (items: Item[], context: QuoteContext): Result => {
150	  const policyBase = policyBaseOf(items);
151	  const riskAdjustedBase = policyBase + itemSurchargesOn(items);
152	  return {
153	    premium: premiumRoundedInMHPCOsFavour(
154	      riskAdjustedBase + policyModifiersOn(policyBase, context) + PROCESSING_FEE,
155	    ),
156	  };
157	};
158	
159	const DEDUCTIBLE_PER_DAMAGE = 100;
160	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
161	
162	const insuranceValueOf = (item: Item): number => catalogueEntryFor(item).insuranceValue;
163	
164	const insuranceSumOf = (items: Item[]): number =>
165	  items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
166	
167	// A policy created by a quote step, tracked by that step's index so later claims
168	// can find it and draw down its cap.
169	type Policy = { items: Item[]; remainingCap: number };
170	
171	const policyFor = (items: Item[]): Policy => ({
172	  items,
173	  remainingCap: insuranceSumOf(items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
174	});
175	
176	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
177	const HALF_REIMBURSEMENT_RATE = 0.5;
178	const FULL_REIMBURSEMENT_RATE = 1;
179	
180	// A distinct rule from the premium's HIGH_ENCHANTMENT_LEVEL, at a distinct
181	// level: this one halves what a claim pays out, that one raises what a policy
182	// costs. They move independently — deliberately not shared.
183	const reimbursesOnlyHalf = (item: Item): boolean =>
184	  enchantmentLevelOf(item) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
185	
186	// How much of the damage the MHPCO reimburses, before the deductible bites.
187	const reimbursementRateFor = (item: Item): number =>
188	  reimbursesOnlyHalf(item) ? HALF_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
189	
190	// A damage names an item type; the policy holds the item it refers to. Which of
191	// several alike items is picked does not matter yet — no test distinguishes them.
192	const damagedItemIn = (policy: Policy, damage: Damage): Item =>
193	  policy.items.find((item) => item.type === damage.itemType)!;
194	
195	const reimbursedAmountFor = (damage: Damage, policy: Policy): number =>
196	  damage.amount * reimbursementRateFor(damagedItemIn(policy, damage));
197	
198	// The deductible bites once per damage, after the reimbursement rate is applied
199	// — never the other way round, which would pay out more.
200	const payoutForDamage = (damage: Damage, policy: Policy): number =>
201	  reimbursedAmountFor(damage, policy) - DEDUCTIBLE_PER_DAMAGE;
202	
203	// One incident can damage several items; each damage is settled on its own
204	// (and so bears its own deductible), and the incident pays out their sum.
205	const payoutForIncident = (incident: Incident, policy: Policy): number =>
206	  incident.damages.reduce((sum, damage) => sum + payoutForDamage(damage, policy), 0);
207	
208	// A payout is drawn from the policy's cap, leaving less for later claims.
209	const capDrawnDownBy = (policy: Policy, payout: number): Policy => ({
210	  ...policy,
211	  remainingCap: policy.remainingCap - payout,
212	});
213	
214	// Settling a claim pays out and draws the cap down by the same amount, so the
215	// result the customer sees is the payout plus the cap that payout left behind.
216	const claimFor = (incident: Incident, policy: Policy): [Result, Policy] => {
217	  const payout = payoutForIncident(incident, policy);
218	  const settledPolicy = capDrawnDownBy(policy, payout);
219	  return [{ payout, remainingCap: settledPolicy.remainingCap }, settledPolicy];
220	};
221	
222	// What the scenario has accumulated before the current step: the results so far,
223	// the history a quote is priced against, and the policies earlier quotes created.
224	type ScenarioState = {
225	  results: Result[];
226	  precedingQuotes: number;
227	  policies: Record<number, Policy>;
228	};
229	
230	const INITIAL_SCENARIO_STATE: ScenarioState = {
231	  results: [],
232	  precedingQuotes: 0,
233	  policies: {},
234	};
235	
236	// Every step reports exactly one result, so recording it is the one thing the
237	// two step kinds always have in common — named once here rather than rebuilt in
238	// each of them.
239	const withResultRecorded = (state: ScenarioState, result: Result): ScenarioState => ({
240	  ...state,
241	  results: [...state.results, result],
242	});
243	
244	const afterQuote = (
245	  state: ScenarioState,
246	  items: Item[],
247	  customer: Customer,
248	  stepIndex: number,
249	): ScenarioState => ({
250	  ...withResultRecorded(
251	    state,
252	    quoteFor(items, { customer, precedingQuotes: state.precedingQuotes }),
253	  ),
254	  precedingQuotes: state.precedingQuotes + 1,
255	  policies: { ...state.policies, [stepIndex]: policyFor(items) },
256	});
257	
258	const afterClaim = (
259	  state: ScenarioState,
260	  policyIndex: number,
261	  incident: Incident,
262	): ScenarioState => {
263	  const [result, settledPolicy] = claimFor(incident, state.policies[policyIndex]);
264	  return {
265	    ...withResultRecorded(state, result),
266	    policies: { ...state.policies, [policyIndex]: settledPolicy },
267	  };
268	};
269	
270	const afterStep = (
271	  state: ScenarioState,
272	  step: Step,
273	  customer: Customer,
274	  stepIndex: number,
275	): ScenarioState =>
276	  step.op === "quote"
277	    ? afterQuote(state, step.items, customer, stepIndex)
278	    : afterClaim(state, step.policy, step.incident);
279	
280	export const runScenario = (scenario: Scenario): { results: Result[] } => {
281	  const { results } = scenario.steps.reduce(
282	    (state, step, stepIndex) => afterStep(state, step, scenario.customer, stepIndex),
283	    INITIAL_SCENARIO_STATE,
284	  );
285	  return { results };
286	};
